import ast as __ast
def __st_calls(src):
    try:
        tree = __ast.parse(src)
    except SyntaxError:
        return ['__syntax_error__']
    names = []
    for n in __ast.walk(tree):
        if isinstance(n, __ast.Call):
            f, parts = n.func, []
            while isinstance(f, __ast.Attribute):
                parts.append(f.attr)
                f = f.value
            if isinstance(f, __ast.Name):
                parts.append(f.id)
            names.append('.'.join(reversed(parts)))
    return names
